python3 -c '
import subprocess, json

class OCSClient:
    def __init__(self):
        self.proc = subprocess.Popen(["OpenCADStudio", "--mcp"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        self._id = 0
        self.call("initialize", {"protocolVersion": "2024-11-05", "capabilities": {}, "clientInfo": {"name": "test", "version": "1.0"}})
        self.call("notifications/initialized", {})
        sessions = self.tool("ocs_sessions", {})
        self.session_id = sessions["result"][0]["session_id"]
        print("Connected! session_id:", self.session_id)

    def call(self, method, params):
        self._id += 1
        req = {"jsonrpc": "2.0", "id": self._id, "method": method, "params": params}
        self.proc.stdin.write(json.dumps(req) + "\n")
        self.proc.stdin.flush()
        line = self.proc.stdout.readline()
        res = json.loads(line)
        if "error" in res:
            raise RuntimeError(res["error"])
        return res.get("result")

    def tool(self, name, args):
        if "ocs_session_id" not in args and name.startswith("ocs_"):
            args["ocs_session_id"] = getattr(self, "session_id", None)
        res = self.call("tools/call", {"name": name, "arguments": args})
        if "structuredContent" in res:
            return res["structuredContent"]
        text = res.get("content", [{}])[0].get("text", "")
        try:
            return json.loads(text)
        except Exception:
            return text

c = OCSClient()
entities = c.tool("ocs_query", {})
print("Entities count:", len(entities) if isinstance(entities, list) else entities)
layers = c.tool("ocs_read", {"op": "records", "parameters": {"collection": "layers"}})
print("Layers:", layers)
'

