arguments.command:
python3 -c '
import xml.etree.ElementTree as ET

tree = ET.parse("/tmp/page1.svg")
root = tree.getroot()

colors = set()
for elem in root.iter():
    for attr in ["stroke", "fill"]:
        val = elem.get(attr)
        if val and val != "none":
            colors.add(val)
    style = elem.get("style", "")
    for part in style.split(";"):
        if ":" in part:
            k, v = part.split(":", 1)
            if k.strip() in ["stroke", "fill"] and v.strip() != "none":
                colors.add(v.strip())

print("Colors in page 1:", sorted(list(colors)))
'

