python3 -c '
import re, math
from PIL import Image, ImageDraw

with open("/tmp/page1.ps") as f:
    text = f.read()

p1 = text[text.find("%%Page: 1 1"):]

matrix_stack = []
curr_matrix = [1, 0, 0, 1, 0, 0]
curr_color = "walls"
paths_by_layer = {}

def apply_mat(m, x, y):
    return m[0]*x + m[2]*y + m[4], m[1]*x + m[3]*y + m[5]

curr_path = []
for line in p1.split("\n"):
    line = line.strip()
    if line == "q":
        matrix_stack.append((list(curr_matrix), curr_color))
    elif line == "Q":
        if matrix_stack:
            curr_matrix, curr_color = matrix_stack.pop()
    elif line.endswith(" cm"):
        clean = line.replace("[", "").replace("]", "")
        parts = clean.split()
        if len(parts) == 7:
            m = [float(x) for x in parts[:6]]
            a1, b1, c1, d1, e1, f1 = curr_matrix
            a2, b2, c2, d2, e2, f2 = m
            curr_matrix = [
                a1*a2 + c1*b2,
                b1*a2 + d1*b2,
                a1*c2 + c1*d2,
                b1*c2 + d1*d2,
                a1*e2 + c1*f2 + e1,
                b1*e2 + d1*f2 + f1
            ]
    elif "[0.584 0 0]" in line:
        curr_color = "windows"
    elif "[0 0.145 0.584]" in line:
        curr_color = "doors_fixtures"
    elif "[0.463 0.463 0.463]" in line:
        curr_color = "stairs"
    elif "[0.145 0.584 0]" in line:
        curr_color = "dimensions"
    elif "[0]" in line and ("SC" in line or "sc" in line):
        curr_color = "walls"
    elif line.endswith(" m"):
        parts = line.split()
        if len(parts) == 3:
            curr_path = [apply_mat(curr_matrix, float(parts[0]), float(parts[1]))]
    elif line.endswith(" l"):
        parts = line.split()
        if len(parts) == 3:
            curr_path.append(apply_mat(curr_matrix, float(parts[0]), float(parts[1])))
    elif line.endswith(" c"):
        parts = line.split()
        if len(parts) == 7:
            curr_path.append(apply_mat(curr_matrix, float(parts[4]), float(parts[5])))
    elif line in ["S", "s", "f", "F", "B", "b"]:
        if len(curr_path) > 1:
            paths_by_layer.setdefault(curr_color, []).append(curr_path)
        curr_path = []

# Now transform to CAD coordinates:
# CAD_X = (709.68 - y_ps) / SF
# CAD_Y = (x_ps - 236.36) / SF
# where SF = 16.72440945
SF = 16.72440945

# Lets render this to an image
W, H = 1600, 800
img = Image.new("RGB", (W, H), "white")
draw = ImageDraw.Draw(img)

# scale to image: 1 meter = 40 pixels, margin = 50
def to_img(cx, cy):
    return int(cx * 40 + 50), int(H - 50 - cy * 40)

colors = {
    "walls": "black",
    "windows": "red",
    "doors_fixtures": "blue",
    "stairs": "gray",
    "dimensions": "green"
}

for layer, paths in paths_by_layer.items():
    col = colors.get(layer, "black")
    for path in paths:
        cad_pts = [((709.68 - py) / SF, (px - 236.36) / SF) for px, py in path]
        img_pts = [to_img(cx, cy) for cx, cy in cad_pts]
        draw.line(img_pts, fill=col, width=1)

img.save("/tmp/extracted_plan_check.png")
print("Saved /tmp/extracted_plan_check.png!")
'

