arguments.command:
python3 -c '
import ezdxf
doc = ezdxf.readfile("/tmp/completed_floor_plan2.dxf")
l1 = doc.layouts.get("Layout1")
for e in l1:
    if e.dxftype() == "LWPOLYLINE":
        print("LWPOLYLINE:", e.get_points())
    elif e.dxftype() == "LINE":
        print("LINE:", e.dxf.start, e.dxf.end)
    elif e.dxftype() == "TEXT":
        print("TEXT:", e.dxf.text, e.dxf.insert)
'

