python3 -c '
import subprocess, json, uuid

proc = subprocess.Popen(["OpenCADStudio", "--mcp"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
def call(method, params, id_num):
    req = {"jsonrpc": "2.0", "id": id_num, "method": method, "params": params}
    proc.stdin.write(json.dumps(req) + "\n")
    proc.stdin.flush()
    return json.loads(proc.stdout.readline()).get("result")

call("initialize", {"protocolVersion": "2024-11-05", "capabilities": {}, "clientInfo": {"name": "test", "version": "1.0"}}, 1)
proc.stdin.write(json.dumps({"jsonrpc": "2.0", "method": "notifications/initialized", "params": {}}) + "\n")
proc.stdin.flush()

sess = call("tools/call", {"name": "ocs_sessions", "arguments": {}}, 2)
session_id = json.loads(sess["content"][0]["text"])[0]["session_id"]

# Open SINGLE_DOOR in Block Editor
call("tools/call", {"name": "ocs_execute", "arguments": {"ocs_session_id": session_id, "request": {
    "op": "run", "cmd": "-BEDIT SINGLE_DOOR", "request_id": str(uuid.uuid4())
}}}, 3)

# Add Flip parameter
res_bp = call("tools/call", {"name": "ocs_execute", "arguments": {"ocs_session_id": session_id, "request": {
    "op": "run", "cmd": "BPARAMETER F 0.5,0 0.5,1 0.5,0.5", "request_id": str(uuid.uuid4())
}}}, 4)
print("BPARAMETER F result:", res_bp)

# Check block info
blocks = call("tools/call", {"name": "ocs_read", "arguments": {"ocs_session_id": session_id, "op": "blocks", "parameters": {"extract_dynamic_properties": True}}}, 5)
for b in json.loads(blocks["content"][0]["text"])["blocks"]:
    if b["name"] == "SINGLE_DOOR":
        print("SINGLE_DOOR block:", json.dumps(b, indent=2))

# Close BEDIT with save
call("tools/call", {"name": "ocs_execute", "arguments": {"ocs_session_id": session_id, "request": {
    "op": "run", "cmd": "BSAVE", "request_id": str(uuid.uuid4())
}}}, 6)
call("tools/call", {"name": "ocs_execute", "arguments": {"ocs_session_id": session_id, "request": {
    "op": "run", "cmd": "BCLOSE", "request_id": str(uuid.uuid4())
}}}, 7)
'

